".slip-glyph-box {
  width: 58px; height: 76px; display: flex; align-items: center; justify-content: center;
  margin-top: 10px;
}
.slip-svg {
  width: 100%; height: 100%; color: #261608;
  filter: drop-shadow(0 1px 0 rgba(255,255,255,.25));
  transition: transform .25s var(--ease), color .25s;
}
.slip:hover .slip-svg {
  transform: scale(1.1);
  color: #120902;
}
.slip-char {
  font-family: var(--serif); font-size: 42px; color: #2a1b0c;
  text-shadow: 0 1px 0 rgba(255,255,255,.22);
}
.slip-tag {
  position: absolute; bottom: 20px; font-family: var(--sans);
  font-size: 11px; color: rgba(38, 26, 12, .88); letter-spacing: 1px;
  white-space: nowrap; pointer-events: none;
}
.slip--key { width: 94px; height: 330px; background: linear-gradient(90deg,#84683f 0%,#c9a769 25%,#e6c98f 50%,#c9a769 75%,#84683f 100%); }
.slip--key .slip-glyph-box {
  width: 68px; height: 90px;
}
.slip--key .slip-svg {
  color: #140801;
  filter: drop-shadow(0 0 12px rgba(184,154,98,.6));
  animation: keyGlowSvg 2.6s ease-in-out infinite;
}
@keyframes keyGlowSvg {
  0%,100% { filter: drop-shadow(0 0 2px rgba(184,154,98,0)); }
  50% { filter: drop-shadow(0 0 18px rgba(184,154,98,.9)); }
}"

