.scene--chip { background: radial-gradient(ellipse at center, #0a1310 0%, #05080a 80%); }

.chip-selector {
  display: flex; justify-content: center; gap: 16px; margin-top: 24px; flex-wrap: wrap;
}
.chip-tab {
  display: flex; flex-direction: column; align-items: center;
  background: rgba(255,255,255,.03); border: 1px solid rgba(114,214,208,.25);
  padding: 10px 22px; border-radius: 6px; cursor: pointer; transition: all .3s var(--ease);
}
.chip-tab:hover { border-color: var(--cyan); background: rgba(114,214,208,.08); }
.chip-tab.is-active {
  border-color: var(--cyan); background: rgba(114,214,208,.16);
  box-shadow: 0 0 22px rgba(114,214,208,.25);
}
.chip-tab__brand {
  font-family: var(--sans); font-size: 11px; letter-spacing: 2px; color: var(--txt-dim);
}
.chip-tab.is-active .chip-tab__brand { color: var(--cyan); font-weight: 600; }
.chip-tab__name {
  font-family: var(--mono); font-size: 13px; color: var(--cold-white); margin-top: 3px;
}

.chip-stage { margin-top: 28px; width: 100%; max-width: 860px; margin-left: auto; margin-right: auto; }
.chip-arch-view { transition: opacity .35s var(--ease); }
.chip-arch-view.is-active { display: block; animation: hudIn .4s var(--ease); }

.die-layout {
  background: #0a0f0d; border: 1px solid rgba(47,111,82,.6); border-radius: 8px;
  padding: 20px; box-shadow: inset 0 0 40px rgba(0,0,0,.8), 0 0 30px rgba(47,111,82,.15);
}
.die-layout--ascend {
  border-color: rgba(114,214,208,.4);
  box-shadow: inset 0 0 40px rgba(0,0,0,.8), 0 0 30px rgba(114,214,208,.15);
}
.die-header {
  display: flex; justify-content: space-between; align-items: center;
  border-bottom: 1px solid rgba(255,255,255,.08); padding-bottom: 10px; margin-bottom: 16px;
