}
.col-title {
  font-family: var(--sans); font-size: 11px; letter-spacing: 2px; color: var(--cyan);
  margin-bottom: 16px; text-transform: uppercase; border-bottom: 1px solid rgba(114,214,208,.15);
  padding-bottom: 8px; text-align: left; font-weight: 600;
}

.col--input-stream {
  display: flex; flex-direction: column;
}
