  background: rgba(114,214,208,.08); padding: 6px 14px; border-radius: 100px;
  border: 1px solid rgba(114,214,208,.25); display: inline-block;
}

.col--model-output {
  display: flex; flex-direction: column; gap: 12px; min-width: 0;
}

/* Transformer 架构与模型块 */
.model-block {
  background: rgba(6,12,20,.85); border: 1px solid rgba(114,214,208,.25); border-radius: 6px;
  padding: 14px 16px; text-align: left; transition: all .35s var(--ease);
}
