"/* FFN 具象化多层前馈神经网络实验台 */
.ffn-lab-section {
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px dashed rgba(114, 214, 208, 0.2);
}
.ffn-lab__header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 8px;
}
.ffn-toolbar {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}
.ffn-tool-label {
  font-family: var(--sans);
  font-size: 11px;
  color: var(--txt-dim);
}
.ffn-tok-btn {
  font-family: var(--serif);
  font-size: 12px;
  padding: 2px 7px;
  border-radius: 4px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.04);
  color: var(--cold-white);
  cursor: pointer;
  transition: all 0.2s;
}
