"  let downSlip = null;
  let downX = 0, downY = 0;

  bambooViewport.addEventListener("pointerdown", (e) => {
    cancelAnimationFrame(momentumId);
    dragging = true;
    dragMoved = false;
    startX = e.clientX;
    startTX = tx;
    lastX = e.clientX;
    lastT = performance.now();
    vel = 0;
    downX = e.clientX;
    downY = e.clientY;
    downSlip = e.target.closest(".slip");
    bambooViewport.classList.add("dragging");
  });

  bambooViewport.addEventListener("pointermove", (e) => {
    if (!dragging) return;
    const dist = Math.hypot(e.clientX - downX, e.clientY - downY);
    if (!dragMoved) {
      if (dist < 8) {
        // 未超过 8px 绝对位移死区，绝不修改 tx，绝不修改 DOM transform，避免浏览器取消原生 click 事件
        return;
      }
      dragMoved = true;
    }
    const now = performance.now();
    const dt = Math.max(1, now - lastT);
    vel = (e.clientX - lastX) / dt;
    lastX = e.clientX;
    lastT = now;
    tx = Math.max(minX, Math.min(maxX, startTX + (e.clientX - startX)));
    applyBamboo();
  });

  function endBambooDrag(e) {
