"/* ============================================================
   移动端横屏模式专项优化 (Landscape Mode · 80% 等比紧凑化缩放)
   消除横屏下芯片 CPU/NPU 与 Transformer Decoder 溢出
   ============================================================ */
@media screen and (orientation: landscape) and (max-height: 560px),
       screen and (orientation: landscape) and (max-width: 1000px) {
  .mobile-orient-fab {
    display: none !important;
  }
  .scene {
    padding: 30px 3vw 25px !important;
    min-height: auto !important;
  }
  .scene-head {
    margin-bottom: 10px !important;
  }
  .scene-kicker {
    margin-bottom: 4px !important;
  }
  .scene-title {
    font-size: 26px !important;
    margin: 2px 0 !important;
  }
  .scene-sub {
    font-size: 12px !important;
    margin-bottom: 8px !important;
  }
  .ring-nav {
    display: none !important;
  }

  /* 核心交互区按要求进行 80% 紧凑等比缩放，彻底消除横屏下芯片与 Decoder 溢出 */
  .chip-lab,
  .ai-pipeline-grid,
  .print-stage,
  .glyph-morph,
  .encode-lab {
    zoom: 0.8 !important;
  }
  @supports not (zoom: 0.8) {
    .chip-lab,
    .ai-pipeline-grid,
    .print-stage {
      transform: scale(0.8) !important;
      transform-origin: top center !important;
    }
  }

  /* 芯片对照台在横屏下保持左右并排 100% 满屏 */
  .chip-split-stage {
    display: grid !important;
    grid-template-columns: 1fr 1fr !important;
    gap: 14px !important;
  }

  /* AI 流水线在横屏缩放后保持 3 列满屏并排 */
  .ai-pipeline-grid {
    display: grid !important;
    grid-template-columns: minmax(180px, 200px) minmax(300px, 1.25fr) minmax(270px, 1.1fr) !important;
    gap: 12px !important;
    overflow-x: visible !important;
  }
}

