"import json
import re
import os
import shutil

transcript_path = r'C:\Users\ASUS\.gemini\antigravity\brain\f03856e4-c9d3-436c-a1aa-2aafe7b22fc3\.system_generated\logs\transcript_full.jsonl'
output_dir = r'f:\desktop\aaa-main'

def sanitize_text(text):
    if not isinstance(text, str):
        return text
    # Sanitize GitHub PAT tokens and other potential secret tokens
    text = re.sub(r'github_pat_[A-Za-z0-9_]+', 'github_pat_***REDACTED***', text)
    text = re.sub(r'ghp_[A-Za-z0-9]{36}', 'ghp_***REDACTED***', text)
    return text

def sanitize_obj(obj):
    if isinstance(obj, str):
        return sanitize_text(obj)
    elif isinstance(obj, list):
        return [sanitize_obj(item) for item in obj]
    elif isinstance(obj, dict):
        return {k: sanitize_obj(v) for k, v in obj.items()}
    return obj

dialogue = []
with open(transcript_path, 'r', encoding='utf-8') as f:
    for line in f:
        data = json.loads(line)
        source = data.get('source')
        mtype = data.get('type')
        content = data.get('content')
        ts = data.get('created_at')

        if source == 'USER_EXPLICIT' and mtype == 'USER_INPUT' and content:
            m = re.search(r'<USER_REQUEST>(.*?)</USER_REQUEST>', content, re.DOTALL)
            clean_content = m.group(1).strip() if m else content.strip()
            clean_content = sanitize_text(clean_content)
            dialogue.append({
                'turn': len(dialogue) + 1,
                'role': 'user',
                'timestamp': ts,
                'content': clean_content
            })
        elif source == 'MODEL' and mtype == 'PLANNER_RESPONSE' and content:
            dialogue.append({
                'turn': len(dialogue) + 1,
                'role': 'assistant',
                'timestamp': ts,
                'content': sanitize_text(content.strip())
            })

print(f"Extracted {len(dialogue)} dialogue messages.")

